insert into public.healthy_substitutions (id,from_foods,to_food,ratio,reason_ar,reason_en,taste_ar,taste_en) values ('oil_olive',array['veg_oil']::text[],'olive_oil',1,'نفس السعرات تقريباً لكن دهون أحادية غير مشبعة أكثر.','About the same calories, more monounsaturated fat.','نكهة أوضح؛ استخدمه لحرارة متوسطة.','More flavour; best for medium heat.') on conflict (id) do update set from_foods=excluded.from_foods, to_food=excluded.to_food, ratio=excluded.ratio, reason_ar=excluded.reason_ar, reason_en=excluded.reason_en, taste_ar=excluded.taste_ar, taste_en=excluded.taste_en;
insert into public.healthy_substitutions (id,from_foods,to_food,ratio,reason_ar,reason_en,taste_ar,taste_en) values ('oil_less',array['veg_oil','olive_oil']::text[],null,0.5,'نصف كمية الزيت يكفي غالباً للتشويح.','Half the oil is usually enough for sautéing.','استخدم مقلاة غير لاصقة وحرّك أكثر.','Use a non-stick pan and stir more often.') on conflict (id) do update set from_foods=excluded.from_foods, to_food=excluded.to_food, ratio=excluded.ratio, reason_ar=excluded.reason_ar, reason_en=excluded.reason_en, taste_ar=excluded.taste_ar, taste_en=excluded.taste_en;
